from itertools import combinations, chain, product

def solve(m, n):
    from itertools import combinations, chain, product

    subsets = []
    for i in range(1, n + 1):
        for combo in combinations(range(1, n + 1), i):
            subsets.append(set(combo))

    num_subsets = len(subsets)
    if num_subsets < 2 * m:
        return False

    # We need to choose 2m distinct subsets and partition them into X and Y
    # such that |X| = m, |Y| = m and X_i \cap Y_j != empty.
    # This is equivalent to:
    # Choose 2m subsets and then pick m of them to be X.
    # Or just iterate over all ways to choose X and Y.

    # To speed up, let's pick m subsets for X first, then m for Y.
    # But we need to ensure X and Y are disjoint.
    # The total number of ways to choose X and Y is comb(num_subsets, m) * comb(num_subsets - m, m)
    # This is still too large.

    # Let's try a different approach for the search.
    # For a fixed X, Y must be a subset of {S : S \cap X_i != empty for all i in X}.
    # Let possible_Y = {S \in Subsets \ X : \forall X_i \in X, S \cap X_i != empty}
    # If |possible_Y| >= m, then we found a solution.

    for X_indices in combinations(range(num_subsets), m):
        X = [subsets[i] for i in X_indices]

        possible_Y_indices = []
        for i in range(num_subsets):
            if i not in X_indices:
                S = subsets[i]
                if all(S.intersection(xi) for xi in X):
                    possible_Y_indices.append(i)

        if len(possible_Y_indices) >= m:
            return True, X, [subsets[i] for i in possible_Y_indices[:m]]

    return False, None, None

for m in range(1, 5):
