from itertools import combinations

def max_m(n):
    subsets = []
    for i in range(1, n + 1):
        for combo in combinations(range(1, n + 1), i):
            subsets.append(set(combo))
    num_subsets = len(subsets)

    best_m = 0
    # Since we can't iterate through all combinations, let's try to
    # only pick X that are "small" or have some property.
    # Actually, let's try a randomized approach to find a large m.
    import random
    for _ in range(10000):
        # Randomly pick m_x and X
        m_x = random.randint(1, num_subsets // 2)
        X_indices = random.sample(range(num_subsets), m_x)
        X = [subsets[i] for i in X_indices]

        possible_Y_indices = []
        for i in range(num_subsets):
            if i not in X_indices:
                S = subsets[i]
                if all(S.intersection(xi) for xi in X):
                    possible_Y_indices.append(i)

        m_y = len(possible_Y_indices)
        m_val = min(m_x, m_y)
        if m_val > best_m:
            best_m = m_val
    return best_m

for n in range(1, 7):
    print(f"n={n}, random_best_m={max_m(n)}")

